import pytest

from check_ai_attribution import find_violations, main


@pytest.mark.parametrize(
    "text",
    [
        "feat: x\n\nCo-Authored-By: Claude <noreply@anthropic.com>",
        "fix: y\n\nco-authored-by: GitHub Copilot <copilot@github.com>",
        "docs: z\n\nClaude-Session: https://claude.ai/code/session_123",
        "Generated with [Claude Code](https://example.com)",
        "🤖 Generated by ChatGPT",
    ],
)
def test_attribution_is_detected(text):
    assert find_violations(text)


@pytest.mark.parametrize(
    "text",
    [
        "feat: add Claude Code skill for handbook reviews",
        "Co-authored-by: Jane Doe <jane@example.com>",
        "docs: explain how Copilot and Gemini read the handbook",
        "The generated report lists findings by rule ID.",
    ],
)
def test_normal_text_is_allowed(text):
    assert find_violations(text) == []


def test_message_file_ignores_git_comments(tmp_path):
    msg = tmp_path / "COMMIT_EDITMSG"
    msg.write_text("feat: ok\n# Co-Authored-By: Claude\n", encoding="utf-8")
    assert main(["--message-file", str(msg)]) == 0


def test_message_file_rejects_trailer(tmp_path):
    msg = tmp_path / "COMMIT_EDITMSG"
    msg.write_text("feat: ok\n\nCo-Authored-By: Claude <noreply@anthropic.com>\n", encoding="utf-8")
    assert main(["--message-file", str(msg)]) == 1
